    for char in s:
        if char == '(':
            stack.append(char)
        elif char == ')':
            if not stack:
                return False
            stack.pop()
    return len(stack) == 0

def match_parens(lst):
    from itertools import permutations

    for perm in permutations(lst):
        concat_str = ''.join(perm)
        if is_balanced(concat_str):
            return 'Yes'

    return 'No'

